INSERT INTO "blog_blocks" ("post_id", "position", "type", "data") VALUES
  ($s$3d38d7f7-9e99-4647-a3eb-28afd52c7fb1$s$, 0, $s$itinerary_with_map$s$, $s${"itineraryId":"3a559e61-29f6-4102-99a9-41a7934cfd6f"}$s$::jsonb),
  ($s$3d38d7f7-9e99-4647-a3eb-28afd52c7fb1$s$, 1, $s$text$s$, $s${"html":"We began our journey in 📌Chaguanas, exploring the vibrant heart of the town. The bustling Municipal Market, a kaleidoscope of colors and aromas, was a feast for the senses. We indulged in the local favorite – doubles – a savory treat that tantalized our taste buds."}$s$::jsonb),
  ($s$3d38d7f7-9e99-4647-a3eb-28afd52c7fb1$s$, 2, $s$image_grid$s$, $s${"images":["aroundtheworld50s/blog/trinidad-and-tobago/4/IMG_1548","aroundtheworld50s/blog/trinidad-and-tobago/4/IMG_1550","aroundtheworld50s/blog/trinidad-and-tobago/4/IMG_1551","aroundtheworld50s/blog/trinidad-and-tobago/4/IMG_1555","aroundtheworld50s/blog/trinidad-and-tobago/4/IMG_1556","aroundtheworld50s/blog/trinidad-and-tobago/4/IMG_1562","aroundtheworld50s/blog/trinidad-and-tobago/4/IMG_1563","aroundtheworld50s/blog/trinidad-and-tobago/4/IMG_1561"]}$s$::jsonb),
  ($s$3d38d7f7-9e99-4647-a3eb-28afd52c7fb1$s$, 3, $s$two_column$s$, $s${"leftType":"image","rightType":"text","leftImage":"aroundtheworld50s/blog/trinidad-and-tobago/4/IMG_1565","leftImageAlt":"img1565","html":"We strolled through the town, admiring the architecture of buildings like the Lion House, a significant landmark with historical significance."}$s$::jsonb),
  ($s$3d38d7f7-9e99-4647-a3eb-28afd52c7fb1$s$, 4, $s$two_column$s$, $s${"leftType":"text","rightType":"image","rightImage":"aroundtheworld50s/blog/trinidad-and-tobago/4/IMG_1570","rightImageAlt":"img1570","html":"Next, we delved into the rich Indian heritage of Trinidad, visiting the 📌Serene Dattatreya Mandir Temple. Walking into the Dattatreya Mandir Temple, you really can't prepare for the feeling of standing there, face-to-face with that enormous statue of Lord Hanuman. It's truly massive, and it made me feel incredibly small in comparison. The whole atmosphere of the temple is just so peaceful and serene, despite the sheer scale of the statue. It's a powerful reminder that Indians are a significant part of Trinidad's population, and their culture deeply enriches the island. 💥 If you're hoping for a semi-private tour, I highly recommend arriving early, just like we did. That way, you'll find the entire place almost empty, which makes the experience even more impactful."}$s$::jsonb),
  ($s$3d38d7f7-9e99-4647-a3eb-28afd52c7fb1$s$, 5, $s$image_grid$s$, $s${"images":["aroundtheworld50s/blog/trinidad-and-tobago/4/IMG_1569","aroundtheworld50s/blog/trinidad-and-tobago/4/IMG_1572","aroundtheworld50s/blog/trinidad-and-tobago/4/IMG_1575","aroundtheworld50s/blog/trinidad-and-tobago/4/IMG_1576"]}$s$::jsonb),
  ($s$3d38d7f7-9e99-4647-a3eb-28afd52c7fb1$s$, 6, $s$text$s$, $s${"html":"And Then: The Magnificent Sea Temple 🌊🙏 After that incredibly moving visit to the Dattatreya Mandir Temple, we headed to our next stop 📌the Sewdass Sadhu Shiva Mandir Temple. This one is just unforgettable, dramatically situated right on the coast, seemingly rising out of the sea itself. It was a beautiful contrast to the inland temple, showing another facet of Trinidad's rich culture. While we were there, we even had a fascinating glimpse of a large Indian gathering for a private event, dressed beautifully in traditional Indian clothes."}$s$::jsonb),
  ($s$3d38d7f7-9e99-4647-a3eb-28afd52c7fb1$s$, 7, $s$image_grid$s$, $s${"images":["aroundtheworld50s/blog/trinidad-and-tobago/4/IMG_1589","aroundtheworld50s/blog/trinidad-and-tobago/4/IMG_1597","aroundtheworld50s/blog/trinidad-and-tobago/4/IMG_1598","aroundtheworld50s/blog/trinidad-and-tobago/4/IMG_1594","aroundtheworld50s/blog/trinidad-and-tobago/4/IMG_1599","aroundtheworld50s/blog/trinidad-and-tobago/4/IMG_1602","aroundtheworld50s/blog/trinidad-and-tobago/4/IMG_1606","aroundtheworld50s/blog/trinidad-and-tobago/4/IMG_1605"]}$s$::jsonb),
  ($s$3d38d7f7-9e99-4647-a3eb-28afd52c7fb1$s$, 8, $s$two_column$s$, $s${"leftType":"text","rightType":"image","rightImage":"aroundtheworld50s/blog/trinidad-and-tobago/4/IMG_1608","rightImageAlt":"img1608","html":"After a delicious lunch at a local eatery, we ascended 📌San Fernando Hill, enjoying panoramic views of the surrounding landscape. The drive up was exhilarating, offering breathtaking vistas at every turn."}$s$::jsonb),
  ($s$3d38d7f7-9e99-4647-a3eb-28afd52c7fb1$s$, 9, $s$text$s$, $s${"html":"The next stop was the legendary 📌La Brea Pitch Lake, a unique natural phenomenon. A local guide (check my tips section) expertly navigated us through the area, explaining this natural asphalt lake's fascinating history and geological wonders. He emphasized the importance of safety, highlighting the dangers of venturing into the pitch without proper guidance. Walking across the surface of the La Brea Pitch Lake was absolutely wild – it literally felt like I was treading on a bubbling black pudding! We had to be super careful with every step because our shoes could easily get stuck in the incredibly sticky pitch, especially since it was a hot day. Our guide was really serious about us sticking to the designated paths, and he even shared some fascinating (and a little bit chilling) stories about the locals. He told us how they've had to move their houses multiple times because of the bubbling, shifting earth underneath them! Can you imagine? Or about visitors who got stuck and lost inside these water bubbles... It was such a humbling experience, a powerful reminder of nature's incredible force and mystery, and how much we really need to respect it. Truly unforgettable."}$s$::jsonb),
  ($s$3d38d7f7-9e99-4647-a3eb-28afd52c7fb1$s$, 10, $s$image_grid$s$, $s${"images":["aroundtheworld50s/blog/trinidad-and-tobago/4/IMG_1618","aroundtheworld50s/blog/trinidad-and-tobago/4/IMG_1621","aroundtheworld50s/blog/trinidad-and-tobago/4/IMG_1624","aroundtheworld50s/blog/trinidad-and-tobago/4/IMG_1625","aroundtheworld50s/blog/trinidad-and-tobago/4/IMG_1627","aroundtheworld50s/blog/trinidad-and-tobago/4/IMG_1629","aroundtheworld50s/blog/trinidad-and-tobago/4/IMG_1631","aroundtheworld50s/blog/trinidad-and-tobago/4/IMG_1636"]}$s$::jsonb),
  ($s$3d38d7f7-9e99-4647-a3eb-28afd52c7fb1$s$, 11, $s$text$s$, $s${"html":"We made our way to the incredible 📌Caroni Bird Sanctuary. We timed it just right for the daily show – and trust me, you absolutely want to confirm your swamp tour departure time way in advance, because those limited spots vanish fast! Also, a quick tip 💥: bring cash, as many of the tour operators prefer it. This huge wetland is one of Trinidad's biggest, and it's just buzzing with all kinds of amazing birds. We even spotted some flamingos gracefully wading in the shallows, adding another splash of beautiful color to the landscape! But the real magic happened as the sun began to set. Suddenly, thousands upon thousands of Scarlet Ibises started flying in, coming back to their roosting spots. They literally painted the entire sky with the most vibrant, fiery red hues. It wasn't just a sight, it was a whole symphony of color and sound that's now absolutely etched into my memory. Truly breathtaking!"}$s$::jsonb),
  ($s$3d38d7f7-9e99-4647-a3eb-28afd52c7fb1$s$, 12, $s$image_grid$s$, $s${"images":["aroundtheworld50s/blog/trinidad-and-tobago/4/IMG_1653","aroundtheworld50s/blog/trinidad-and-tobago/4/IMG_1654","aroundtheworld50s/blog/trinidad-and-tobago/4/IMG_1672","aroundtheworld50s/blog/trinidad-and-tobago/4/IMG_1670","aroundtheworld50s/blog/trinidad-and-tobago/4/IMG_1693","aroundtheworld50s/blog/trinidad-and-tobago/4/IMG_1688","aroundtheworld50s/blog/trinidad-and-tobago/4/IMG_1699","aroundtheworld50s/blog/trinidad-and-tobago/4/IMG_1720"]}$s$::jsonb);
